/** Label for a design lane that was downgraded to a plain build (no model repair ran). */
export const DESIGN_DOWNGRADE = "design lane downgraded to plain build (no repair)";
const REPAIR_SAY = /^(.*?)\.? Fixing it automatically \(fix (\d+) of \d+\)/;

/** One label per model repair, e.g. "perf-spawn-in-loop", "No design found", "Sound check problems", "compile errors". */
export function repairTriggers(rec: TriggerRecord | null | undefined): string[] {
  if (!rec) return [];
  const out: string[] = [];
  for (const e of rec.events ?? []) {
    // not a model repair, but a design lane that shipped as a plain build: visible as its own label (no Designer editability)
    if (/^No design needed: keeping the plugin code as written/i.test(String(e?.message ?? ""))) { out.push(DESIGN_DOWNGRADE); continue; }
    const m = REPAIR_SAY.exec(String(e?.message ?? ""));
    if (!m) continue;
    const say = m[1].trim(), fix = Number(m[2]);
    if (/^Pre-check found/i.test(say)) {
      const rules = [...new Set((rec.precheck ?? []).filter((p) => p.attempt === fix && p.rule).map((p) => String(p.rule)))];
      out.push(...(rules.length ? rules : ["pre-check (unnamed rule)"]));
    } else if (/^Found \d+ known runtime problem/i.test(say)) {
      const rules = [...new Set((rec.precheck ?? []).filter((p) => p.attempt === fix && p.rule).map((p) => String(p.rule)))];
      out.push(...(rules.length ? rules.map((r) => `warning:${r}`) : ["runtime warning"]));
    } else if (/^Compiler found/i.test(say)) out.push("compile errors");
    else if (/^No design found/i.test(say)) out.push("No design found");
    else if (/^(Sound|Texture|Asset|Data pack|Creature|Design) check found/i.test(say)) out.push(`${say.replace(/ found .*$/i, "")} problems`);
    else if (/setup problem/i.test(say)) out.push("setup problems");
    else out.push(say.replace(/\d+/g, "N"));
  }
  return out;
}

